using TimeDuration = Rational; // Invariant: >= 0

struct TimeRange {
    TimePoint start;
    TimeDuration duration;

    constexpr TimeRange() noexcept = default;
    constexpr TimeRange(TimePoint s, TimeDuration d) noexcept : start(s), duration(d) {}

    [[nodiscard]] TimePoint EndExclusive() const noexcept { return start + duration; }
