// Portable half-precision (FP16) emulation with IEEE-754 compliance
// ======================================================================
struct half {
    uint16_t x;
    half() = default;
    half(uint16_t v) : x(v) {}
    explicit half(float f) { x = float_to_half(f); }
    operator float() const { return half_to_float(x); }

    static uint16_t float_to_half(float f) {
        uint32_t u = *reinterpret_cast<const uint32_t*>(&f);
        uint32_t sign = (u >> 16) & 0x8000;
        int32_t  exp  = (u >> 23) & 0xFF;
        uint32_t mant = u & 0x7FFFFF;

        if (exp == 0xFF) { // NaN/Inf
            return sign | 0x7C00 | (mant ? 0x200 : 0);
        }
        if (exp == 0) { // Zero or subnormal
            if (mant == 0) return sign;
            // Normalize subnormal
            while ((mant & 0x800000) == 0) { mant <<= 1; exp--; }
            exp++;
            mant &= 0x7FFFFF;
        }
        // Round to nearest even (10-bit mantissa)
        int32_t new_exp = exp - 127 + 15;
        if (new_exp >= 31) return sign | 0x7C00; // Overflow -> Inf
        if (new_exp <= 0) { // Underflow -> subnormal or zero
            int shift = 1 - new_exp;
            if (shift >= 25) return sign;
            uint32_t round_bit = (mant >> (shift - 1)) & 1;
            uint32_t sticky = (mant & ((1u << (shift - 1)) - 1)) != 0;
            mant >>= shift;
            if (round_bit && (sticky || (mant & 1))) mant++;
            if (mant == 0) return sign;
            return sign | mant;
        }
        // Normal rounding
        uint32_t round_bit = (mant >> 12) & 1;
        uint32_t sticky = (mant & 0xFFF) != 0;
        mant >>= 13;
        if (round_bit && (sticky || (mant & 1))) {
            mant++;
            if (mant == 0x400) { mant = 0; new_exp++; }
        }
        return sign | (new_exp << 10) | mant;
    }

    static float half_to_float(uint16_t h) {
        uint32_t sign = (h >> 15) & 1;
        uint32_t exp  = (h >> 10) & 0x1F;
        uint32_t mant = h & 0x3FF;
        if (exp == 0) {
            if (mant == 0) return sign ? -0.0f : 0.0f;
            // Subnormal
            while ((mant & 0x400) == 0) { mant <<= 1; exp--; }
            exp++;
            mant &= 0x3FF;
        } else if (exp == 0x1F) {
            return mant ? std::numeric_limits<float>::quiet_NaN() : (sign ? -INFINITY : INFINITY);
        }
        uint32_t f = (sign << 31) | ((exp - 15 + 127) << 23) | (mant << 13);
        return *reinterpret_cast<float*>(&f);
    }
};

