    float get_global_sum() const { return smem_global_sum; }
};

// ======================================================================
// Online Softmax per warp (32 elements) with numerical stability
// ======================================================================
// Each thread holds one element. Returns normalized value for that thread.
__device__ half warp_online_softmax(Warp& warp, int lane_id, half x) {
    float val = static_cast<float>(x);
    // Step 1: Warp-wide max reduction
    float warp_max = warp.shfl_xor_reduce_max(val, lane_id);
    // Step 2: Compute exp(val - warp_max) and sum
    float exp_val = expf(val - warp_max);
    float warp_sum = warp.shfl_xor_reduce_sum(exp_val, lane_id);
    // Step 3: Normalize
    float result = exp_val / warp_sum;
    return half(result);
}

// ======================================================================
// Kernel: Softmax over N=4096 elements per row (M=1024 rows)
// Each block processes one row. 4 warps per block, each warp handles 1024 elements.
// ======================================================================
__global__ void softmax_kernel(const half* __restrict__ input,
                               half* __restrict__ output,
                               int M, int N) {
    // Simulated block/thread indices
    int row = blockIdx.x;
    int tid = threadIdx.x;
    int warp_id = tid / WARP_SIZE;
    int lane_id = tid % WARP_SIZE;

    extern __shared__ char dynamic_smem[];
    Block* block = reinterpret_cast<Block*>(dynamic_smem);

    // Each warp processes N / WARPS_PER_BLOCK = 1024 elements
    int warp_start = warp_id * (N / WARPS_PER_BLOCK);
    int warp_end   = warp_start + (N / WARPS_PER_BLOCK);

    // Online softmax requires two passes if we want exact global max/sum.
    // We use a two-pass approach: first find global max, then compute sum, then normalize.
    // Pass 1: Find max in warp's chunk
    float warp_max = -INFINITY;
    for (int i = warp_start + lane_id; i < warp_end; i += WARP_SIZE) {
        float val = static_cast<float>(input[row * N + i]);
        warp_max = fmaxf(warp_max, val);
    }
    warp_max = block->warps[warp_id].shfl_xor_reduce_max(warp_max, lane_id);

    // Pass 2: Compute sum of exp(val - global_max)
    // First, block-wide max reduction
    block->block_reduce_max_sum(warp_id, lane_id, warp_max, 0.0f);
    __syncthreads();
    float global_max = block->get_global_max();

    // Now compute sum of exp(val - global_max) in warp's chunk
    float warp_sum = 0.0f;
    for (int i = warp_start + lane_id; i < warp_end; i += WARP_SIZE) {
        float val = static_cast<float>(input[row * N + i]);
        warp_sum += expf(val - global_max);
    }
    warp_sum = block->warps[warp_id].shfl_xor_reduce_sum(warp_sum, lane_id);

    // Block-wide sum reduction
    block->block_reduce_max_sum(warp_id, lane_id, 0.0f, warp_sum);
    __syncthreads();
    float global_sum = block->get_global_sum();

    // Pass 3: Normalize and write output
    for (int i = warp_start + lane_id; i < warp_end; i += WARP_SIZE) {
        float val = static_cast<float>(input[row * N + i]);
        float out = expf(val - global_max) / global_sum;
        output[row * N + i] = half(out);
    }
}

