double compute_spherical_excess(const std::vector<Vec3>& verts) {
    size_t n = verts.size();
    if (n < 3) return 0.0;

    // Triangulation Fan from Vertex 0.
    // Assumes polygon is simple, CCW (positive area).
    // We sum signed excesses.
    double total_excess = 0.0;

    // Pre-compute centroid for planar fallback center (more stable than V0 for large fans)
    Vec3 centroid = {0,0,0};
    for (const auto& v : verts) centroid += v;
    centroid = normalize(centroid);

    for (size_t i = 1; i + 1 < n; ++i) {
        const Vec3& v0 = verts[0];
        const Vec3& v1 = verts[i];
        const Vec3& v2 = verts[i+1];

        // Compute sides
        double a = spherical_side(v1, v2); // Opposite v0
        double b = spherical_side(v0, v2); // Opposite v1
        double c = spherical_side(v0, v1); // Opposite v2

        double max_side = std::max({a, b, c});

        double excess = 0.0;

        if (max_side < wgs84::PLANAR_THRESHOLD_RAD) {
            // Hybrid Planar Fallback: LAEA at Centroid (or v0)
            // Using centroid ensures projection center is inside polygon for convex shapes.
            excess = planar_excess_laea(centroid, v1, v2); // Triangle (centroid, v1, v2) ? No.
            // Fan triangulation is (v0, v1, v2). 
            // Planar area of (v0, v1, v2) in LAEA centered at centroid.
            // But LAEA at centroid maps centroid to (0,0). 
            // We need area of triangle (v0, v1, v2).
            // Shoelace on projected coords of v0, v1, v2.

            // Project v0, v1, v2 to LAEA at centroid
            auto project = [&](const Vec3& v) -> std::pair<double, double> {
                double dot_vc = dot(v, centroid);
                if (dot_vc > 1.0) dot_vc = 1.0;
                if (dot_vc < -1.0) dot_vc = -1.0;
                double k = std::sqrt(2.0 / (1.0 + dot_vc));

                // Basis at centroid
                Vec3 Z(0,0,1);
                Vec3 east = cross(Z, centroid);
                double east_n = norm(east);
                Vec3 e_norm, north;
                if (east_n < wgs84::EPS) {
                    e_norm = Vec3(1,0,0);
                    north = (centroid.z > 0) ? Vec3(0,1,0) : Vec3(0,-1,0);
                } else {
                    e_norm = east / east_n;
                    north = cross(centroid, e_norm);
                }
                return { k * dot(v, e_norm), k * dot(v, north) };
            };

            auto [x0, y0] = project(v0);
            auto [x1, y1] = project(v1);
            auto [x2, y2] = project(v2);

            // Shoelace formula for triangle area
            excess = 0.5 * std::abs( x0*(y1-y2) + x1*(y2-y0) + x2*(y0-y1) );

            // Determine sign (winding order).
            // On sphere, sign of triple product (v0, v1, v2) gives orientation relative to origin.
            // But we want orientation relative to polygon interior (usually "up" / outward normal).
            // For CCW polygon on sphere (viewed from outside), vertices appear CCW from origin?
            // Standard: Right-hand rule. Normal = cross(v1-v0, v2-v0) approx.
            // Spherical excess sign = sign( dot(v0, cross(v1, v2)) ) for triangle fan from origin?
            // Actually, Girard's theorem gives positive excess for triangles covering < 2pi.
            // The sign of the spherical excess for a geodesic triangle is positive if vertices are ordered CCW 
            // when viewed from the *exterior* of the sphere (i.e., the normal points outward).
            // Triple product T = dot(v0, cross(v1, v2)).
            // If T > 0, vertices are CCW from outside -> Interior is to the left of edges -> Positive Area.
            double trip = dot(v0, cross(v1, v2));
            if (trip < 0) excess = -excess;

        } else {
            // L'Huilier's Theorem
            // Sort sides descending for stability: a >= b >= c
            double sides[3] = {a, b, c};
            std::sort(sides, sides+3, std::greater<double>());
            excess = lhuilier_excess(sides[0], sides[1], sides[2]);

            // Sign via Triple Product (Orientation)
