constexpr int WARP_SIZE = 32;
constexpr uint32_t FULL_MASK = 0xFFFFFFFFu;

template <typename T>
inline T shfl_xor_sync_emul(uint32_t mask, T val, int lane_mask, int width = WARP_SIZE) {
