#define PERIPH_BASE_ADDR        0x40001000U
#define PERIPH_SIZE             0x1000U
#define BURST_ALIGNMENT         64U

#define REG_CTRL_OFFSET         0x00U
#define REG_STATUS_OFFSET       0x04U
#define REG_DATA_OFFSET         0x08U
#define REG_IRQ_MASK_OFFSET     0x0CU

#define REG_CTRL                (PERIPH_BASE_ADDR + REG_CTRL_OFFSET)
#define REG_STATUS              (PERIPH_BASE_ADDR + REG_STATUS_OFFSET)
#define REG_DATA                (PERIPH_BASE_ADDR + REG_DATA_OFFSET)
#define REG_IRQ_MASK            (PERIPH_BASE_ADDR + REG_IRQ_MASK_OFFSET)

#define CTRL_ENABLE_BIT         (1U << 0)
#define CTRL_RESET_BIT          (1U << 1)
#define CTRL_DMA_EN_BIT         (1U << 2)
#define CTRL_IRQ_EN_BIT         (1U << 3)

#define STATUS_DONE_BIT         (1U << 0)
#define STATUS_ERROR_BIT        (1U << 1)
#define STATUS_FIFO_FULL_BIT    (1U << 2)
#define STATUS_FIFO_EMPTY_BIT   (1U << 3)
#define STATUS_BUSY_BIT         (1U << 4)

#define IRQ_MASK_DONE_BIT       (1U << 0)
#define IRQ_MASK_ERROR_BIT      (1U << 1)
#define IRQ_MASK_FIFO_THRESH    (1U << 2)

static_assert((PERIPH_BASE_ADDR % BURST_ALIGNMENT) == 0U,
              "Peripheral base address must be 64-byte aligned for burst transfers");
static_assert((REG_CTRL_OFFSET % 4U) == 0U, "Register offsets must be 32-bit aligned");
static_assert((REG_STATUS_OFFSET % 4U) == 0U, "Register offsets must be 32-bit aligned");
static_assert((REG_DATA_OFFSET % 4U) == 0U, "Register offsets must be 32-bit aligned");
static_assert((REG_IRQ_MASK_OFFSET % 4U) == 0U, "Register offsets must be 32-bit aligned");

typedef struct {
    volatile uint32_t ctrl;
    volatile uint32_t status;
    volatile uint32_t data;
    volatile uint32_t irq_mask;
} __attribute__((aligned(4))) periph_regs_t;

static periph_regs_t * const periph = (periph_regs_t *)PERIPH_BASE_ADDR;

static inline void dmb_ish(void) {
    __asm__ volatile ("dmb ish" ::: "memory");
}

static inline void dsb_ish(void) {
    __asm__ volatile ("dsb ish" ::: "memory");
}

static inline void isb(void) {
    __asm__ volatile ("isb" ::: "memory");
}

static inline uint32_t reg_read(volatile const uint32_t *addr) {
    uint32_t val = *addr;
    dmb_ish();
    return val;
}

static inline void reg_write(volatile uint32_t *addr, uint32_t val) {
    dmb_ish();
    *addr = val;
    dmb_ish();
}

static inline void reg_set_bits(volatile uint32_t *addr, uint32_t mask) {
    uint32_t val = reg_read(addr);
    reg_write(addr, val | mask);
}

static inline void reg_clear_bits(volatile uint32_t *addr, uint32_t mask) {
    uint32_t val = reg_read(addr);
    reg_write(addr, val & ~mask);
}

bool periph_init(void) {
    reg_write(&periph->ctrl, 0U);
    reg_write(&periph->irq_mask, 0U);
    reg_write(&periph->status, UINT32_MAX);
    dsb_ish();
    return true;
}

void periph_enable(void) {
    reg_set_bits(&periph->ctrl, CTRL_ENABLE_BIT);
}

void periph_disable(void) {
    reg_clear_bits(&periph->ctrl, CTRL_ENABLE_BIT);
}

void periph_reset(void) {
    reg_set_bits(&periph->ctrl, CTRL_RESET_BIT);
    dsb_ish();
    reg_clear_bits(&periph->ctrl, CTRL_RESET_BIT);
}

void periph_dma_enable(bool enable) {
    if (enable) {
        reg_set_bits(&periph->ctrl, CTRL_DMA_EN_BIT);
    } else {
        reg_clear_bits(&periph->ctrl, CTRL_DMA_EN_BIT);
    }
}

void periph_irq_enable(uint32_t mask) {
    reg_set_bits(&periph->irq_mask, mask & (IRQ_MASK_DONE_BIT | IRQ_MASK_ERROR_BIT | IRQ_MASK_FIFO_THRESH));
}

void periph_irq_disable(uint32_t mask) {
    reg_clear_bits(&periph->irq_mask, mask & (IRQ_MASK_DONE_BIT | IRQ_MASK_ERROR_BIT | IRQ_MASK_FIFO_THRESH));
}

uint32_t periph_get_status(void) {
    return reg_read(&periph->status);
}

void periph_clear_status(uint32_t mask) {
    reg_write(&periph->status, mask & (STATUS_DONE_BIT | STATUS_ERROR_BIT | STATUS_FIFO_FULL_BIT | STATUS_FIFO_EMPTY_BIT));
}

bool periph_is_busy(void) {
    return (reg_read(&periph->status) & STATUS_BUSY_BIT) != 0U;
}

bool periph_is_fifo_full(void) {
    return (reg_read(&periph->status) & STATUS_FIFO_FULL_BIT) != 0U;
}

bool periph_is_fifo_empty(void) {
    return (reg_read(&periph->status) & STATUS_FIFO_EMPTY_BIT) != 0U;
}

bool periph_write_data(uint32_t data) {
    if (periph_is_fifo_full()) {
        return false;
    }
    reg_write(&periph->data, data);
    return true;
}

bool periph_read_data(uint32_t *out_data) {
    if (periph_is_fifo_empty()) {
        return false;
    }
    *out_data = reg_read(&periph->data);
    return true;
}

size_t periph_write_burst(const uint32_t *src, size_t count) {
    assert(((uintptr_t)src % BURST_ALIGNMENT) == 0U);
    assert((count * sizeof(uint32_t)) % BURST_ALIGNMENT == 0U);

    size_t written = 0;
    for (size_t i = 0; i < count; ++i) {
        if (periph_is_fifo_full()) {
            break;
        }
        reg_write(&periph->data, src[i]);
        ++written;
    }
    dsb_ish();
    return written;
}

size_t periph_read_burst(uint32_t *dst, size_t count) {
    assert(((uintptr_t)dst % BURST_ALIGNMENT) == 0U);
    assert((count * sizeof(uint32_t)) % BURST_ALIGNMENT == 0U);

    size_t read = 0;
    for (size_t i = 0; i < count; ++i) {
        if (periph_is_fifo_empty()) {
            break;
        }
        dst[i] = reg_read(&periph->data);
        ++read;
    }
    dsb_ish();
    return read;
}

uint32_t periph_get_ctrl(void) {
    return reg_read(&periph->ctrl);
}

uint32_t periph_get_irq_mask(void) {
    return reg_read(&periph->irq_mask);
}
