    Track* track = comp.add_track();
    MediaReference mr("ClipA", TimeRange(RationalTime(0,24), RationalTime(100,24)), 24);

    // Clip starts at -10 frames (handles negative offset in track)
    // Track source_range_start = 0. Clip offset = -10.
    // Effective start = -10. 
