// Portable half-precision (FP16) storage and conversion
using half = uint16_t;

inline float half_to_float(half h) {
    // IEEE-754 binary16 -> binary32 conversion (exact)
    uint32_t sign = (h >> 15) & 0x1;
    uint32_t exp  = (h >> 10) & 0x1F;
    uint32_t mant = h & 0x3FF;

    if (exp == 0) {
        if (mant == 0) return sign ? -0.0f : 0.0f;
        // Subnormal: renormalize
        while ((mant & 0x400) == 0) { mant <<= 1; exp--; }
        exp++; mant &= 0x3FF;
    } else if (exp == 0x1F) {
        return mant ? std::nanf("") : (sign ? -INFINITY : INFINITY);
    }
    uint32_t f = (sign << 31) | ((exp + 112) << 23) | (mant << 13);
    return *reinterpret_cast<float*>(&f);
}

inline half float_to_half(float f) {
    uint32_t u = *reinterpret_cast<uint32_t*>(&f);
    uint32_t sign = (u >> 31) & 0x1;
    int32_t  exp  = ((u >> 23) & 0xFF) - 112;
    uint32_t mant = u & 0x7FFFFF;

    if (exp <= 0) {
        if (exp < -10) return sign << 15; // Underflow to zero
        mant |= 0x800000;
        half h = static_cast<half>((mant >> (13 - exp)) + 0xFFF); // Round-to-nearest-even
        return (sign << 15) | h;
    } else if (exp >= 0x1F) {
        return (sign << 15) | 0x7C00; // Overflow to Inf
    }
    return (sign << 15) | (exp << 10) | ((mant + 0xFFF) >> 13);
}

// Warp emulation (32 lanes)
constexpr int WARP_SIZE = 32;
constexpr uint32_t FULL_MASK = 0xFFFFFFFF;

struct Warp {
    float regs[WARP_SIZE]; // FP32 compute registers

    // Butterfly XOR reduction (max or sum)
    template <typename Op>
    void shfl_xor_reduce(Op op, int lane) {
        for (int offset = 16; offset > 0; offset >>= 1) {
            float other = regs[lane ^ offset];
            regs[lane] = op(regs[lane], other);
        }
    }

    // Online softmax for one warp (32 elements)
    void online_softmax(const half* input, half* output, int lane) {
        // Load & convert to FP32
        regs[lane] = half_to_float(input[lane]);

        // Phase 1: max reduction
        shfl_xor_reduce([](float a, float b){ return fmaxf(a, b); }, lane);
        float max_val = regs[0]; // Broadcast from lane 0 (all lanes have same value after reduction)

        // Phase 2: exp(x - max) and sum reduction
        float exp_val = expf(regs[lane] - max_val);
        regs[lane] = exp_val;
        shfl_xor_reduce([](float a, float b){ return a + b; }, lane);
        float sum_exp = regs[0];

        // Phase 3: normalize and store
        output[lane] = float_to_half(exp_val / sum_exp);
    }
};

// Reference CPU softmax (FP32) for verification
void cpu_softmax(const half* in, half* out, int n) {
    std::vector<float> f(n);
    float maxv = -INFINITY;
    for (int i = 0; i < n; ++i) {
        f[i] = half_to_float(in[i]);
        maxv = fmaxf(maxv, f[i]);
    }
    float sum = 0.0f;
    for (int i = 0; i < n; ++i) {
        f[i] = expf(f[i] - maxv);
        sum += f[i];
    }
    for (int i = 0; i < n; ++i) out[i] = float_to_half(f[i] / sum);
}

// ULP distance for FP16
int ulp_distance(half a, half b) {
    uint16_t ua = a, ub = b;
    if ((ua ^ ub) & 0x8000) return 0xFFFF; // Different signs
    return abs(static_cast<int>(ua) - static_cast<int>(ub));
}

