            Rational cur_start = out[i].global_start();
            assert(prev_end == cur_start); // no gaps
        }
    }

    double ms = std::chrono::duration<double, std::milli>(t1 - t0).count();
    std::cout << "Processed " << clips.size() << " clips in " << std::fixed << std::setprecision(3)
