/* lockfree_dma_ring.c
 * Production‑grade single‑producer single‑consumer DMA descriptor ring.
 * Simulated hardware registers are backed by a static RAM array.
 * Compiles with: gcc -std=c11 -Wall -Wextra -O2 lockfree_dma_ring.c -o lockfree_dma_ring
 */

#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>
#include <assert.h>

/* -------------------------------------------------------------------------- */
/* Simulated hardware registers (base 0x4000_1000)                           */
/* -------------------------------------------------------------------------- */
#define DMA_BASE_ADDR   0x40001000U
enum {
    REG_CTRL   = 0x00U,
    REG_STATUS = 0x04U,   /* Write‑1‑to‑clear */
    REG_DATA   = 0x08U,
    REG_IRQMASK= 0x0CU
};

static uint32_t sim_regs[4];   /* 0:CTRL, 1:STATUS, 2:DATA, 3:IRQMASK */

/* Register write helper – handles W1C for STATUS */
static inline void reg_write(uint32_t offset, uint32_t value)
{
    size_t idx = (offset >> 2U);
    if (offset == REG_STATUS) {
        /* Write‑1‑to‑clear */
        sim_regs[idx] &= ~value;
    } else {
        sim_regs[idx] = value;
    }
}

/* Register read helper */
static inline uint32_t reg_read(uint32_t offset)
{
    return sim_regs[(offset >> 2U)];
}

/* -------------------------------------------------------------------------- */
/* Portable memory barriers – map to GCC built‑ins for host simulation       */
/* -------------------------------------------------------------------------- */
#define DMB() __sync_synchronize()   /* Data Memory Barrier */
#define DSB() __sync_synchronize()   /* Data Synchronization Barrier */

/* -------------------------------------------------------------------------- */
/* DMA descriptor definition                                                 */
/* -------------------------------------------------------------------------- */
typedef struct {
    uint32_t src_addr;
    uint32_t dst_addr;
    uint32_t length;   /* bytes, must be multiple of 64 */
    uint32_t control;  /* hardware‑specific flags */
} dma_desc_t;

/* -------------------------------------------------------------------------- */
/* Ring buffer structure                                                     */
/* -------------------------------------------------------------------------- */
typedef struct {
    volatile dma_desc_t *desc;   /* descriptor array in RAM */
    uint32_t size;               /* power‑of‑two */
    uint32_t mask;               /* size‑1 */
    volatile uint32_t prod_idx;  /* producer (write) index */
    volatile uint32_t cons_idx;  /* consumer (read) index */
} dma_ring_t;

/* -------------------------------------------------------------------------- */
/* Ring API                                                                   */
/* -------------------------------------------------------------------------- */

/* Initialise a ring. `buf` must be `size` elements long and `size` a power‑of‑2 */
static inline void dma_ring_init(dma_ring_t *ring,
                                 dma_desc_t *buf,
                                 uint32_t size)
{
    assert(ring != NULL);
    assert(buf != NULL);
    assert(size && ((size & (size - 1U)) == 0U));   /* power‑of‑2 */

    ring->desc     = buf;
    ring->size     = size;
    ring->mask     = size - 1U;
    ring->prod_idx = 0U;
    ring->cons_idx = 0U;
}

/* Return true if ring is full */
static inline bool dma_ring_full(const dma_ring_t *ring)
{
    return ((ring->prod_idx - ring->cons_idx) == ring->size);
}

/* Return true if ring is empty */
static inline bool dma_ring_empty(const dma_ring_t *ring)
{
    return (ring->prod_idx == ring->cons_idx);
}

/* Enqueue a descriptor – returns false if ring is full */
static bool dma_ring_enqueue(dma_ring_t *ring, const dma_desc_t *d)
{
    if (dma_ring_full(ring))
        return false;

    uint32_t idx = ring->prod_idx & ring->mask;
    /* Write descriptor into RAM */
    ring->desc[idx] = *d;

    /* Ensure descriptor is visible before we publish the index */
    DMB();

    /* Publish new producer index */
    ring->prod_idx++;

    /* Kick hardware: write descriptor address (simulated) */
    reg_write(REG_DATA, (uint32_t)(uintptr_t)&ring->desc[idx]);

    return true;
}

/* Dequeue a descriptor – returns false if ring is empty */
static bool dma_ring_dequeue(dma_ring_t *ring, dma_desc_t *out)
{
    if (dma_ring_empty(ring))
        return false;

    uint32_t idx = ring->cons_idx & ring->mask;
    *out = ring->desc[idx];

    /* Ensure we have read the descriptor before we advance consumer */
    DMB();

    ring->cons_idx++;

    /* Acknowledge completion to hardware – clear a status bit (simulated) */
    reg_write(REG_STATUS, 0x1U);   /* assume bit0 = descriptor‑done */

    return true;
}

/* -------------------------------------------------------------------------- */
/* Simple unit‑test harness                                                   */
/* -------------------------------------------------------------------------- */
int main(void)
{
    /* Simulated hardware reset */
    for (size_t i = 0; i < 4; ++i) sim_regs[i] = 0U;

    /* Allocate a descriptor buffer (must be 64‑byte aligned for realism) */
    static dma_desc_t __attribute__((aligned(64))) ring_buf[8];
    dma_ring_t ring;
    dma_ring_init(&ring, ring_buf, 8U);

    /* Prepare test descriptors */
    dma_desc_t d1 = { .src_addr = 0x20000000U,
                     .dst_addr = 0x30000000U,
                     .length   = 128U,
                     .control  = 0x0U };
    dma_desc_t d2 = { .src_addr = 0x20000100U,
                     .dst_addr = 0x30000100U,
                     .length   = 256U,
                     .control  = 0x1U };
    dma_desc_t d3 = { .src_addr = 0x20000200U,
                     .dst_addr = 0x30000200U,
                     .length   = 64U,
                     .control  = 0x2U };

    /* Enqueue descriptors */
    assert(dma_ring_enqueue(&ring, &d1));
    assert(dma_ring_enqueue(&ring, &d2));
    assert(dma_ring_enqueue(&ring, &d3));
    assert(!dma_ring_empty(&ring));
    assert(dma_ring_full(&ring) == false);

    /* Verify that hardware DATA register received the last descriptor address */
    assert(reg_read(REG_DATA) == (uint32_t)(uintptr_t)&ring.desc[2]);

    /* Dequeue and validate order */
    dma_desc_t out;
    assert(dma_ring_dequeue(&ring, &out));
    assert(out.src_addr == d1.src_addr && out.length == d1.length);
    assert(reg_read(REG_STATUS) == 0U);   /* STATUS bit cleared by W1C */

    assert(dma_ring_dequeue(&ring, &out));
    assert(out.src_addr == d2.src_addr && out.control == d2.control);

    assert(dma_ring_dequeue(&ring, &out));
    assert(out.dst_addr == d3.dst_addr && out.length == d3.length);

    /* Ring should now be empty */
    assert(dma_ring_empty(&ring));

    /* Attempt to dequeue from empty ring – should fail */
    assert(!dma_ring_dequeue(&ring, &out));

    /* Fill ring completely to test full condition */
    for (uint32_t i = 0; i < ring.size; ++i) {
        dma_desc_t tmp = { .src_addr = i,
                          .dst_addr = i + 0x1000U,
                          .length   = 64U,
                          .control  = 0U };
        bool ok = dma_ring_enqueue(&ring, &tmp);
        assert(ok);
    }
    assert(dma_ring_full(&ring));
    /* One more enqueue must fail */
    assert(!dma_ring_enqueue(&ring, &d1));

    return 0;
}
