// FlashAttention-Style Online Rescaling Tile Accumulator Simulation
// C++17, strict compiler flags, no external dependencies

#include <cstdint>
#include <cstddef>
#include <cstring>
#include <cmath>
#include <vector>
#include <array>
#include <algorithm>
#include <atomic>
#include <cassert>
#include <iostream>
#include <random>
#include <limits>

constexpr std::size_t M = 1024;      // rows
constexpr std::size_t N = 4096;      // columns
constexpr std::size_t K = 128;       // inner dimension
constexpr std::size_t TILE_N = 64;   // tile width
constexpr std::size_t PAD = 8;       // padding to avoid bank conflicts
static_assert((TILE_N + PAD) % 8 == 0, "Tile stride must be multiple of 8 for bank conflict avoidance");

// Helper: generate random float in [-1,1]
float randf(std::mt19937 &rng) {
    std::uniform_real_distribution<float> dist(-1.0f, 1.0f);
    return dist(rng);
}

// Reference softmax implementation (naive)
void compute_reference(const std::vector<float> &Q, const std::vector<float> &K,
                       std::vector<float> &softmax_out) {
    softmax_out.resize(M * N);
    for (std::size_t i = 0; i < M; ++i) {
        // compute max over all columns
        float row_max = -std::numeric_limits<float>::infinity();
        for (std::size_t j = 0; j < N; ++j) {
            float score = 0.0f;
            for (std::size_t k = 0; k < K; ++k) {
                score += Q[i * K + k] * K[j * K + k];
            }
            if (score > row_max) row_max = score;
        }
        // compute sum of exp(score - max)
        float sum_exp = 0.0f;
        for (std::size_t j = 0; j < N; ++j) {
            float score = 0.0f;
            for (std::size_t k = 0; k < K; ++k) {
                score += Q[i * K + k] * K[j * K + k];
            }
            sum_exp += std::exp(score - row_max);
        }
        // normalize
        for (std::size_t j = 0; j < N; ++j) {
            float score = 0.0f;
            for (std::size_t k = 0; k < K; ++k) {
                score += Q[i * K + k] * K[j * K + k];
            }
            softmax_out[i * N + j] = std::exp(score - row_max) / sum_exp;
        }
    }
}

// Tile-based accumulator simulation
void compute_tile_accumulator(const std::vector<float> &Q, const std::vector<float> &K,
                              std::vector<float> &softmax_out) {
    softmax_out.resize(M * N);
    // Shared memory simulation: K x (TILE_N + PAD)
    const std::size_t SHMEM_COLS = TILE_N + PAD;
    std::vector<float> shmem(K * SHMEM_COLS, 0.0f);

    // For each row, maintain running max and sum
    std::vector<float> row_max(M, -std::numeric_limits<float>::infinity());
    std::vector<float> row_sum(M, 0.0f);

    for (std::size_t tile_start = 0; tile_start < N; tile_start += TILE_N) {
        const std::size_t cur_tile_n = std::min(TILE_N, N - tile_start);

        // Load tile of K into shared memory (K^T layout)
        for (std::size_t k = 0; k < K; ++k) {
            for (std::size_t col = 0; col < cur_tile_n; ++col) {
                shmem[k * SHMEM_COLS + col] = K[(tile_start + col) * K + k];
            }
        }

        // For each row, compute tile_max and tile_exp_sum
        for (std::size_t i = 0; i < M; ++i) {
            // Compute tile_max
            float tile_max = -std::numeric_limits<float>::infinity();
            for (std::size_t k = 0; k < K; ++k) {
                const float qik = Q[i * K + k];
                for (std::size_t col = 0; col < cur_tile_n; ++col) {
                    float score = qik * shmem[k * SHMEM_COLS + col];
                    if (score > tile_max) tile_max = score;
                }
            }

            // Compute tile_exp_sum
            float tile_exp_sum = 0.0f;
            for (std::size_t k = 0; k < K; ++k) {
                const float qik = Q[i * K + k];
                for (std::size_t col = 0; col < cur_tile_n; ++col) {
                    float score = qik * shmem[k * SHMEM_COLS + col];
                    tile_exp_sum += std::exp(score - tile_max);
                }
            }

            // Update running max and sum
            float old_max = row_max[i];
            float new_max = std::max(old_max, tile_max);
            float scale = std::exp(old_max - new_max);
            row_sum[i] = row_sum[i] * scale + tile_exp_sum;
            row_max[i] = new_max;
        }
    }

    // Final normalization
    for (std::size_t i = 0; i < M; ++i) {
        float denom = row_sum[i];
        for (std::size_t j = 0; j < N; ++j) {
            // Recompute score for this element
            float score = 0.0f;
            for (std::size_t k = 0; k < K; ++k) {
                score += Q[i * K + k] * K[j * K + k];
            }
            softmax_out[i * N + j] = std::exp(score - row_max[i]) / denom;
        }
    }
}

int main() {
    // Seed random generator
    std::mt19937 rng(12345);

    // Allocate Q (M x K) and K (N x K)
    std::vector<float> Q(M * K);
    std::vector<float> K(N * K);
    for (auto &x : Q) x = randf(rng);
    for (auto &x : K) x = randf(rng);

    // Compute reference
    std::vector<float> ref_softmax;
    compute_reference(Q, K, ref_softmax);

    // Compute tile-based accumulator
    std::vector<float> tile_softmax;
    compute_tile_accumulator(Q, K, tile_softmax);

    // Verify results
    const float eps = 1e-4f;
    for (std::size_t i = 0; i < M; ++i) {
        float sum_ref = 0.0f, sum_tile = 0.0f;
        for (std::size_t j = 0; j < N; ++j) {
            float diff = std::fabs(ref_softmax[i * N + j] - tile_softmax[i * N + j]);
            assert(diff < eps && "Softmax values differ beyond tolerance");
            sum_ref += ref_softmax[i * N + j];
            sum_tile += tile_softmax[i * N + j];
        }
        assert(std::fabs(sum_ref - 1.0f) < eps && "Reference row sum not 1");
        assert(std::fabs(sum_tile - 1.0f) < eps && "Tile row sum not 1");
    }

    std::cout << "All tests passed successfully.\n";
    return 0;
}
