// SIMD-Vectorized SoA Frustum & Bounding-Box Culler
// Compile with: g++ -std=c++17 -O2 -march=native -Wall -Wextra -o culler culler.cpp
#include <cstdint>
#include <cstddef>
#include <cstring>
#include <cmath>
#include <vector>
#include <array>
#include <algorithm>
#include <atomic>
#include <cassert>
#include <iostream>
#include <random>
#include <chrono>
#include <immintrin.h> // AVX intrinsics

// -----------------------------------------------------------------------------
// Aligned allocator for 64‑byte alignment
// -----------------------------------------------------------------------------
template <typename T, std::size_t Alignment>
struct AlignedAllocator {
    using value_type = T;
    AlignedAllocator() noexcept {}
    template <typename U> AlignedAllocator(const AlignedAllocator<U, Alignment>&) noexcept {}
    T* allocate(std::size_t n) {
        std::size_t sz = n * sizeof(T);
        void* ptr = nullptr;
        if (posix_memalign(&ptr, Alignment, sz) != 0) throw std::bad_alloc();
        return static_cast<T*>(ptr);
    }
    void deallocate(T* p, std::size_t) noexcept {
        free(p);
    }
};

template <typename T, std::size_t Alignment>
bool operator==(const AlignedAllocator<T, Alignment>&, const AlignedAllocator<T, Alignment>&) noexcept { return true; }

template <typename T, std::size_t Alignment>
bool operator!=(const AlignedAllocator<T, Alignment>& a, const AlignedAllocator<T, Alignment>& b) noexcept { return !(a == b); }

// -----------------------------------------------------------------------------
// Plane definition: normal (nx,ny,nz) and distance d (plane equation: nx*x+ny*y+nz*z + d = 0)
// -----------------------------------------------------------------------------
struct Plane {
    float nx, ny, nz, d;
};

// -----------------------------------------------------------------------------
// SIMD culling function
// -----------------------------------------------------------------------------
void cull(const Plane* planes, int numPlanes,
          const float* minX, const float* minY, const float* minZ,
          const float* maxX, const float* maxY, const float* maxZ,
          int count, std::vector<int>& outIndices) {
    outIndices.clear();
    outIndices.reserve(count);
    const int simdWidth = 8; // AVX 256‑bit = 8 floats
    for (int i = 0; i < count; i += simdWidth) {
        int chunk = std::min(simdWidth, count - i);
        // Load min/max into SIMD registers
        __m256 vMinX = _mm256_load_ps(minX + i);
        __m256 vMinY = _mm256_load_ps(minY + i);
        __m256 vMinZ = _mm256_load_ps(minZ + i);
        __m256 vMaxX = _mm256_load_ps(maxX + i);
        __m256 vMaxY = _mm256_load_ps(maxY + i);
        __m256 vMaxZ = _mm256_load_ps(maxZ + i);
        // Mask for valid lanes
        __m256i maskValid = _mm256_set1_epi32(-1);
        if (chunk < simdWidth) {
            std::uint32_t mask = (1u << chunk) - 1;
            maskValid = _mm256_set1_epi32(static_cast<int>(mask));
        }

        // For each plane, test all boxes in the chunk
        bool outside[simdWidth] = {false};
        for (int p = 0; p < numPlanes; ++p) {
            const Plane& pl = planes[p];
            __m256 vNx = _mm256_set1_ps(pl.nx);
            __m256 vNy = _mm256_set1_ps(pl.ny);
            __m256 vNz = _mm256_set1_ps(pl.nz);
            __m256 vD  = _mm256_set1_ps(pl.d);
            // Compute farthest point along normal
            __m256 vPX = _mm256_blendv_ps(vMinX, vMaxX, _mm256_cmp_ps(vNx, _mm256_setzero_ps(), _CMP_GE_OS));
            __m256 vPY = _mm256_blendv_ps(vMinY, vMaxY, _mm256_cmp_ps(vNy, _mm256_setzero_ps(), _CMP_GE_OS));
            __m256 vPZ = _mm256_blendv_ps(vMinZ, vMaxZ, _mm256_cmp_ps(vNz, _mm256_setzero_ps(), _CMP_GE_OS));
            __m256 dist = _mm256_fmadd_ps(vPX, vNx, _mm256_fmadd_ps(vPY, vNy, _mm256_fmadd_ps(vPZ, vNz, vD)));
            // If dist < 0, all boxes in this lane are outside for this plane
            __m256 mask = _mm256_cmp_ps(dist, _mm256_setzero_ps(), _CMP_LT_OS);
            // Update outside flags
            for (int lane = 0; lane < simdWidth; ++lane) {
                if (outside[lane]) continue;
                if (_mm256_movemask_ps(mask) & (1 << lane)) outside[lane] = true;
            }
        }

        // Append visible indices
        for (int lane = 0; lane < chunk; ++lane) {
            if (!outside[lane]) outIndices.push_back(i + lane);
        }
    }
}

// -----------------------------------------------------------------------------
// Helper to generate random float in [min, max]
// -----------------------------------------------------------------------------
float randFloat(std::mt19937& rng, float min, float max) {
    std::uniform_real_distribution<float> dist(min, max);
    return dist(rng);
}

// -----------------------------------------------------------------------------
// Main benchmark and invariant verifier
// -----------------------------------------------------------------------------
int main() {
    constexpr int NUM_CLIPS = 10000;
    constexpr int NUM_PLANES = 6;
    // Allocate SoA arrays with 64‑byte alignment
    std::vector<float, AlignedAllocator<float, 64>> minX(NUM_CLIPS);
    std::vector<float, AlignedAllocator<float, 64>> minY(NUM_CLIPS);
    std::vector<float, AlignedAllocator<float, 64>> minZ(NUM_CLIPS);
    std::vector<float, AlignedAllocator<float, 64>> maxX(NUM_CLIPS);
    std::vector<float, AlignedAllocator<float, 64>> maxY(NUM_CLIPS);
    std::vector<float, AlignedAllocator<float, 64>> maxZ(NUM_CLIPS);

    // Verify alignment
    assert((reinterpret_cast<std::uintptr_t>(minX.data()) % 64) == 0);
    assert((reinterpret_cast<std::uintptr_t>(minY.data()) % 64) == 0);
    assert((reinterpret_cast<std::uintptr_t>(minZ.data()) % 64) == 0);
    assert((reinterpret_cast<std::uintptr_t>(maxX.data()) % 64) == 0);
    assert((reinterpret_cast<std::uintptr_t>(maxY.data()) % 64) == 0);
    assert((reinterpret_cast<std::uintptr_t>(maxZ.data()) % 64) == 0);

    // Random number generator
    std::mt19937 rng(42);
    // Generate random boxes and random nested offsets
    for (int i = 0; i < NUM_CLIPS; ++i) {
        float cx = randFloat(rng, -1000.0f, 1000.0f);
        float cy = randFloat(rng, -1000.0f, 1000.0f);
        float cz = randFloat(rng, -1000.0f, 1000.0f);
        float w  = randFloat(rng, 1.0f, 50.0f);
        float h  = randFloat(rng, 1.0f, 50.0f);
        float d  = randFloat(rng, 1.0f, 50.0f);
        // Random nested offset
        float ox = randFloat(rng, -10.0f, 10.0f);
        float oy = randFloat(rng, -10.0f, 10.0f);
        float oz = randFloat(rng, -10.0f, 10.0f);
        minX[i] = cx - w/2 + ox;
        minY[i] = cy - h/2 + oy;
        minZ[i] = cz - d/2 + oz;
        maxX[i] = cx + w/2 + ox;
        maxY[i] = cy + h/2 + oy;
        maxZ[i] = cz + d/2 + oz;
    }

    // Define a simple view frustum (axis-aligned for simplicity)
    Plane planes[NUM_PLANES] = {
        { 1.0f,  0.0f,  0.0f, -500.0f}, // Left
        {-1.0f,  0.0f,  0.0f, -500.0f}, // Right
        { 0.0f,  1.0f,  0.0f, -500.0f}, // Bottom
        { 0.0f, -1.0f,  0.0f, -500.0f}, // Top
        { 0.0f,  0.0f,  1.0f, -500.0f}, // Near
        { 0.0f,  0.0f, -1.0f, -500.0f}  // Far
    };

    std::vector<int> visibleIndices;
    visibleIndices.reserve(NUM_CLIPS);

    // Benchmark
    auto start = std::chrono::high_resolution_clock::now();
    cull(planes, NUM_PLANES,
         minX.data(), minY.data(), minZ.data(),
         maxX.data(), maxY.data(), maxZ.data(),
         NUM_CLIPS, visibleIndices);
    auto end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double, std::milli> ms = end - start;

    std::cout << "Culling completed in " << ms.count() << " ms\n";
    std::cout << "Visible clips: " << visibleIndices.size() << " / " << NUM_CLIPS << "\n";

    // Invariant checks
    assert(visibleIndices.size() <= NUM_CLIPS);
    for (int idx : visibleIndices) {
        assert(idx >= 0 && idx < NUM_CLIPS);
    }

    return 0;
}
