    const int M = 2;
    const int N = 16;
    std::vector<std::vector<Half>> mat(M, std::vector<Half>(N));
    for (int m = 0; m < M; ++m) {
        for (int n = 0; n < N; ++n) {
            float val = static_cast<float>(rand()) / RAND_MAX * 10.0f - 5.0f; // [-5,5]
