#include <atomic>
#include <cassert>
#include <iostream>
#include <chrono>
#include <iomanip>

struct Clip {
    alignas(64) std::atomic<uint32_t> ref_count{0};
    Clip* parent = nullptr;
};

template <typename T>
class IntrusivePtr {
    T* ptr_;
public:
    IntrusivePtr() noexcept : ptr_(nullptr) {}

    explicit IntrusivePtr(T* p) noexcept : ptr_(p) { if (ptr_) inc(); }

    IntrusivePtr(const IntrusivePtr& other) noexcept : ptr_(other.ptr_) { if (ptr_) inc(); }

    IntrusivePtr(IntrusivePtr&& other) noexcept : ptr_(other.ptr_) { other.ptr_ = nullptr; }

    ~IntrusivePtr() { if (ptr_) dec(); }

    IntrusivePtr& operator=(const IntrusivePtr& other) noexcept {
        if (this != &other) {
            if (ptr_) dec();
            ptr_ = other.ptr_;
            if (ptr_) inc();
        }
        return *this;
    }

    IntrusivePtr& operator=(IntrusivePtr&& other) noexcept {
        if (this != &other) {
            if (ptr_) dec();
            ptr_ = other.ptr_;
            other.ptr_ = nullptr;
        }
        return *this;
    }

    T* get() const noexcept { return ptr_; }
    T& operator*() const noexcept { return *ptr_; }
    T* operator->() const noexcept { return ptr_; }
    explicit operator bool() const noexcept { return ptr_ != nullptr; }

private:
    void inc() { ptr_->ref_count.fetch_add(1, std::memory_order_relaxed); }
    void dec() {
        if (ptr_->ref_count.fetch_sub(1, std::memory_order_acq_rel) == 1) {
            // No deallocation; memory managed by the vector.
        }
    }
};

int main() {
    constexpr std::size_t NUM_CLIPS = 10000;

    // Preallocate storage for clips
    std::vector<Clip> clips;
    clips.reserve(NUM_CLIPS);
    for (std::size_t i = 0; i < NUM_CLIPS; ++i) {
        clips.emplace_back();
        if (i > 0) {
            clips[i].parent = &clips[i - 1];
        }
    }

    // Verify alignment and initial ref counts
    for (std::size_t i = 0; i < NUM_CLIPS; ++i) {
        assert((reinterpret_cast<std::uintptr_t>(&clips[i]) % 64) == 0);
        assert(clips[i].ref_count.load(std::memory_order_relaxed) == 0);
    }

    // Benchmark creation of intrusive pointers
    std::vector<IntrusivePtr<Clip>> ptrs;
    ptrs.reserve(NUM_CLIPS);
    auto start = std::chrono::high_resolution_clock::now();
    for (std::size_t i = 0; i < NUM_CLIPS; ++i) {
        ptrs.emplace_back(&clips[i]);
    }
    auto end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> elapsed = end - start;
    std::cout << "Created " << NUM_CLIPS << " IntrusivePtr in "
              << std::fixed << std::setprecision(6) << elapsed.count() << " s\n";

    // Verify ref counts after pointer construction
    for (std::size_t i = 0; i < NUM_CLIPS; ++i) {
        assert(clips[i].ref_count.load(std::memory_order_relaxed) == 1);
    }

    // Create additional pointers to parent clips to test nested composition
    std::vector<IntrusivePtr<Clip>> parent_ptrs;
    parent_ptrs.reserve(NUM_CLIPS);
    for (std::size_t i = 0; i < NUM_CLIPS; ++i) {
        if (clips[i].parent) {
            parent_ptrs.emplace_back(clips[i].parent);
        }
    }

    // Verify ref counts after adding parent pointers
    for (std::size_t i = 0; i < NUM_CLIPS; ++i) {
        uint32_t expected = 1; // own ptr
        if (clips[i].parent) {
            expected += 1; // parent pointer from child
        }
        assert(clips[i].ref_count.load(std::memory_order_relaxed) == expected);
    }

    // Destroy all pointers
    ptrs.clear();
    parent_ptrs.clear();

    // Verify that all ref counts have returned to zero
    for (std::size_t i = 0; i < NUM_CLIPS; ++i) {
        assert(clips[i].ref_count.load(std::memory_order_relaxed) == 0);
    }

    std::cout << "All invariants satisfied. Test passed.\n";
    return 0;
}
