    TimelineClip* add_clip(uint64_t id, uint64_t start, uint64_t dur,
                           uint32_t depth, uint32_t layer, uint64_t parent,
                           uint32_t flags) noexcept {
        assert(clip_count_ < MAX_CLIPS);
