        uint32_t layer = i % 16;
        uint64_t start = BASE_TIME + (i * 1000); // 1μs stagger
        uint64_t duration = 500'000 + (i % 1000) * 1000; // 0.5ms - 1.5ms
        uint64_t parent_offset = depth * 10'000'000; // 10ms per depth level
        uint32_t flags = (i % 2) ? 1 : 0;

