#include <cmath>
#include <vector>
#include <array>
#include <algorithm>
#include <cassert>
#include <iostream>
#include <random>

// ---------- bfloat16 emulation ----------
struct bfloat16 {
    uint16_t data;
    bfloat16() = default;
    bfloat16(uint16_t d) : data(d) {}
    explicit bfloat16(float f) {
        uint32_t u;
        std::memcpy(&u, &f, sizeof(float));
        data = static_cast<uint16_t>(u >> 16);
    }
    operator float() const {
        uint32_t u = static_cast<uint32_t>(data) << 16;
        float f;
        std::memcpy(&f, &u, sizeof(float));
        return f;
    }
    bool operator==(const bfloat16& other) const { return data == other.data; }
};

// ---------- Simulation parameters ----------
constexpr int M = 1024;
constexpr int N = 4096;
constexpr int TILE_DIM = 32;
constexpr int PADDED_DIM = 33; // 32+1 for bank conflict freedom
constexpr int BLOCK_THREADS = 128;
constexpr int WARP_SIZE = 32;
constexpr int ELEMENTS_PER_THREAD = (TILE_DIM * TILE_DIM) / BLOCK_THREADS; // 8
constexpr size_t SHARED_MEM_BYTES = TILE_DIM * PADDED_DIM * sizeof(bfloat16); // 2112 bytes
static_assert(SHARED_MEM_BYTES <= 48 * 1024, "Shared memory exceeds 48KB budget");

// ---------- Kernel simulation ----------
void simulate_transpose_block(
    const bfloat16* __restrict__ input,
    bfloat16* __restrict__ output,
    int tile_row, int tile_col
) {
    // Shared memory tile: 32 rows x 33 columns (padded)
    alignas(16) bfloat16 tile[TILE_DIM][PADDED_DIM];

    // Phase 1: Coalesced global load into shared memory (row-major)
    for (int tid = 0; tid < BLOCK_THREADS; ++tid) {
        for (int i = 0; i < ELEMENTS_PER_THREAD; ++i) {
            int idx = tid * ELEMENTS_PER_THREAD + i;
            int row = idx / TILE_DIM;
            int col = idx % TILE_DIM;
            int global_row = tile_row + row;
            int global_col = tile_col + col;
            if (global_row < M && global_col < N) {
                tile[row][col] = input[global_row * N + global_col];
            } else {
                tile[row][col] = bfloat16(0.0f);
            }
        }
    }
    // __syncthreads() implicit in sequential simulation

    // Phase 2: Transposed write from shared memory to global (column-major -> row-major in output)
    for (int tid = 0; tid < BLOCK_THREADS; ++tid) {
        for (int i = 0; i < ELEMENTS_PER_THREAD; ++i) {
            int idx = tid * ELEMENTS_PER_THREAD + i;
            int row = idx / TILE_DIM; // row in transposed tile (0..31)
            int col = idx % TILE_DIM; // col in transposed tile (0..31)
            // Shared memory access: tile[col][row] (transposed) with padded column stride
            bfloat16 val = tile[col][row];
            int global_row_out = tile_col + row; // output matrix is N x M
            int global_col_out = tile_row + col;
            if (global_row_out < N && global_col_out < M) {
                output[global_row_out * M + global_col_out] = val;
            }
        }
    }
}

// ---------- Host reference transpose ----------
void host_transpose(const std::vector<bfloat16>& input, std::vector<bfloat16>& output) {
    for (int r = 0; r < M; ++r) {
        for (int c = 0; c < N; ++c) {
            output[c * M + r] = input[r * N + c];
        }
    }
}

// ---------- Main test harness ----------
int main() {
    // Initialize input with random bfloat16 values
    std::vector<bfloat16> input(M * N);
    std::vector<bfloat16> output(N * M);
    std::vector<bfloat16> reference(N * M);

    std::mt19937 rng(42);
    std::uniform_real_distribution<float> dist(-100.0f, 100.0f);
    for (auto& v : input) v = bfloat16(dist(rng));

    // Launch simulated kernel for all blocks
    constexpr int grid_x = N / TILE_DIM; // 128
    constexpr int grid_y = M / TILE_DIM; // 32
    for (int by = 0; by < grid_y; ++by) {
        for (int bx = 0; bx < grid_x; ++bx) {
            simulate_transpose_block(input.data(), output.data(), by * TILE_DIM, bx * TILE_DIM);
        }
    }

    // Compute reference
    host_transpose(input, reference);

    // Verify numerical equivalence (exact match since transpose is a permutation)
    for (size_t i = 0; i < output.size(); ++i) {
        assert((output[i] == reference[i]));
    }

    // Verify shared memory padding prevents bank conflicts (conceptual)
    // In a real GPU, 32 banks, 4-byte width. Padded dimension 33 ensures consecutive rows map to different banks.
    assert((PADDED_DIM % 32 != 0)); // 33 % 32 = 1 != 0

    std::cout << "All tests passed. Shared memory used: " << SHARED_MEM_BYTES << " bytes.\n";
    return 0;
}
