```cpp
#include <cstdint>
#include <cstddef>
#include <cstring>
#include <cmath>
#include <vector>
#include <array>
#include <algorithm>
#include <atomic>
#include <cassert>
#include <iostream>
#include <random>
#include <limits>
#include <iomanip>

// ------------------------------------------------------------
// Simulation of GPU execution environment
// ------------------------------------------------------------
constexpr int WARP_SIZE = 32;
constexpr int BLOCK_DIM = 128;
constexpr int M = 1024;
constexpr int N = 4096;
constexpr int K = 128;          // group size (128 elements per scale)
constexpr int GROUPS_PER_ROW = N / K;  // 32
constexpr int PACKED_PER_ROW = N / 2;  // 2048 bytes (uint8_t)
constexpr int SHARED_MEM_X_BYTES = N * sizeof(float);  // 16 KiB

// ------------------------------------------------------------
// FP4 (E2M1) to FP32 conversion
// Format: 1 sign | 2 exponent | 1 mantissa (bias = 1)
// Values: 0, ±0.5, ±1, ±1.5, ±2, ±3, ±4, ±6
// ------------------------------------------------------------
inline float fp4_e2m1_to_fp32(uint8_t fp4) {
    // fp4 in [0, 15]
    uint8_t sign = (fp4 >> 3) & 0x1;
    uint8_t exp  = (fp4 >> 1) & 0x3;
    uint8_t mant = fp4 & 0x1;

    float val;
    if (exp == 0) {                 // subnormal
        val = mant * 0.5f;          // 0 or 0.5
    } else {
        // normal: 1.mant * 2^(exp-1)
        val = (1.0f + mant * 0.5f) * std::ldexp(1.0f, int(exp) - 1);
    }
    return sign ? -val : val;
}

// ------------------------------------------------------------
// Reference GEMV (FP32 accumulation) for verification
// ------------------------------------------------------------
void reference_gemv(const std::vector<uint8_t>& A_packed,
                    const std::vector<float>& scales,
                    const std::vector<float>& x,
                    std::vector<float>& y_ref) {
    for (int row = 0; row < M; ++row) {
        float sum = 0.0f;
        for (int col = 0; col < N; ++col) {
            int byte_idx = row * PACKED_PER_ROW + col / 2;
            uint8_t packed = A_packed[byte_idx];
            uint8_t fp4 = (col & 1) ? (packed & 0xF) : (packed >> 4);
            float w = fp4_e2m1_to_fp32(fp4) * scales[row * GROUPS_PER_ROW + col / K];
            sum += w * x[col];
        }
        y_ref[row] = sum;
    }
}

// ------------------------------------------------------------
// Simulated kernel with shared memory for x vector
// ------------------------------------------------------------
void simulated_kernel(const std::vector<uint8_t>& A_packed,
                      const std::vector<float>& scales,
                      const std::vector<float>& x,
                      std::vector<float>& y) {
    // Shared memory for x (simulated as local array per block)
    // In real kernel: __shared__ float s_x[N];
    // We simulate block-level cooperation by loading x once per block.
    std::vector<float> s_x(N);

    const int gridDim = (M + BLOCK_DIM - 1) / BLOCK_DIM;  // 8 blocks

    for (int blockIdx = 0; blockIdx < gridDim; ++blockIdx) {
        // Cooperative load of x into shared memory (simulated)
        for (int tid = 0; tid < BLOCK_DIM; ++tid) {
            for (int i = tid; i < N; i += BLOCK_DIM) {
                s_x[i] = x[i];
            }
        }
        // __syncthreads() implicit

        // Each thread computes one output row
        for (int tid = 0; tid < BLOCK_DIM; ++tid) {
            int row = blockIdx * BLOCK_DIM + tid;
            if (row >= M) continue;

            // Load scales for this row (32 floats) into registers
            float local_scales[GROUPS_PER_ROW];
            for (int g = 0; g < GROUPS_PER_ROW; ++g) {
                local_scales[g] = scales[row * GROUPS_PER_ROW + g];
            }

            float sum = 0.0f;
            for (int col = 0; col < N; ++col) {
                int byte_idx = row * PACKED_PER_ROW + col / 2;
                uint8_t packed = A_packed[byte_idx];
                uint8_t fp4 = (col & 1) ? (packed & 0xF) : (packed >> 4);
                float w = fp4_e2m1_to_fp32(fp4) * local_scales[col / K];
                sum += w * s_x[col];
            }
            y[row] = sum;
        }
    }
}

// ------------------------------------------------------------
// Test harness with random data and numerical verification
// ------------------------------------------------------------
int main() {
    std::mt19937_64 rng(0xC0FFEE);
    std::uniform_int_distribution<uint8_t> dist_u8(0, 15);   // FP4 values
    std::uniform_real_distribution<float> dist_scale(-100.0f, 100.0f);
    std::uniform_real_distribution<float> dist_x(-10.0f, 10.0f);

    // Allocate data
    std::vector<uint8_t> A_packed(M * PACKED_PER_ROW);
    std::vector<float> scales(M * GROUPS_PER_ROW);
    std::vector<float> x(N);
    std::vector<float> y(M);
    std::vector<float> y_ref(M);

    // Initialize with random data including extreme values for overflow/underflow test
    for (auto& v : A_packed) v = dist_u8(rng);
    for (auto& v : scales) {
        // Mix normal, large, and small scales
        float r = dist_scale(rng);
        if (rng() % 100 < 5) r *= 1e4f;      // large
        if (rng() % 100 < 5) r *= 1e-4f;     // small
        v = r;
    }
    for (auto& v : x) v = dist_x(rng);

    // Run reference and simulated kernel
    reference_gemv(A_packed, scales, x, y_ref);
    simulated_kernel(A_packed, scales, x, y);

    // Verify numerical stability (relative error < 1e-5)
    float max_rel_err = 0.0f;
    int max_idx = -1;
    for (int i = 0; i < M; ++i) {
        float ref = y_ref[i];
        float res = y[i];
        float abs_err = std::abs(ref - res);
        float rel_err = (std::abs(ref) > 1e-7f) ? abs_err / std::abs(ref) : abs_err;
        if (rel_err > max_rel_err) {
            max_rel_err = rel_err;
            max_idx = i;
        }
    }

    std::cout << "Max relative error: " << max_rel_err << " at row " << max_idx << "\n";
    std::cout << "Reference: " << y_ref[max_idx] << " Kernel: " << y[max_idx] << "\n";

    // Assert numerical stability
    assert((max_rel_err < 1e-5f) && "Numerical stability check failed: relative error too large");

    // Additional sanity: check that FP16 overflow/underflow would have occurred but FP32 didn't
    // We can't directly test FP16 here, but we trust FP32 accumulation.

    std::cout << "All tests passed.\n";
    return 0;
}
